import { gs, GlideRecord, GlideDateTime } from '@servicenow/glide';
export function calcVolunteerHours(current, previous) {
    var checkIn = current.getValue('check_in');
    var checkOut = current.getValue('check_out');
    if (!checkIn || !checkOut)
        return;
    var inTime = new GlideDateTime(checkIn);
    var outTime = new GlideDateTime(checkOut);
    var diffMs = outTime.getNumericValue() - inTime.getNumericValue();
    var actualHours = diffMs / (1000 * 60 * 60);
    if (actualHours < 0)
        actualHours = 0;
    // Cap at scheduled event duration
    var eventId = current.getValue('event');
    var scheduledHours = 0;
    if (eventId) {
        var evt = new GlideRecord('x_2248447_csr_ma_2_event');
        if (evt.get(eventId)) {
            scheduledHours = parseFloat(evt.getValue('scheduled_hours')) || 8;
        }
    }
    var creditedHours = Math.min(actualHours, scheduledHours);
    creditedHours = Math.round(creditedHours * 100) / 100;
    current.setValue('volunteer_hours', Math.round(actualHours * 100) / 100);
    if (!current.getValue('original_hours')) {
        current.setValue('original_hours', creditedHours);
    }
    current.setValue('credited_hours', creditedHours);
    current.setValue('status', 'completed');
}
export function awardBadges(current, previous) {
    var newStatus = current.getValue('status');
    var oldStatus = previous.getValue('status');
    if (newStatus !== 'completed' || oldStatus === 'completed')
        return;
    var employeeId = current.getValue('employee');
    var eventId = current.getValue('event');
    if (!employeeId)
        return;
    // Get fiscal year from event
    var fiscalYear = '';
    if (eventId) {
        var evt = new GlideRecord('x_2248447_csr_ma_2_event');
        if (evt.get(eventId)) {
            var eventDate = evt.getValue('event_date');
            if (eventDate) {
                fiscalYear = eventDate.substring(0, 4);
            }
        }
    }
    if (!fiscalYear) {
        var now = new GlideDateTime();
        fiscalYear = '' + now.getYearUTC();
    }
    // Calculate total credited hours for employee in this fiscal year
    var totalHours = 0;
    var att = new GlideRecord('x_2248447_csr_ma_2_attendance');
    att.addQuery('employee', employeeId);
    att.addQuery('status', 'completed');
    att.addQuery('event.event_date', '>=', fiscalYear + '-01-01');
    att.addQuery('event.event_date', '<=', fiscalYear + '-12-31');
    att.query();
    while (att.next()) {
        totalHours += parseFloat(att.getValue('credited_hours')) || 0;
    }
    // Add current record's hours
    totalHours += parseFloat(current.getValue('credited_hours')) || 0;
    // Check milestones
    var milestoneStr = gs.getProperty('x_2248447_csr_ma_2.badge_milestones') || '10,25,50';
    var milestones = milestoneStr.split(',');
    var badgeMap = { '10': 'bronze_10', '25': 'silver_25', '50': 'gold_50' };
    for (var i = 0; i < milestones.length; i++) {
        var milestone = parseInt(milestones[i].trim());
        if (totalHours >= milestone) {
            var badgeLevel = badgeMap['' + milestone] || ('badge_' + milestone);
            // Check if already awarded
            var existing = new GlideRecord('x_2248447_csr_ma_2_recognition');
            existing.addQuery('employee', employeeId);
            existing.addQuery('badge_level', badgeLevel);
            existing.addQuery('fiscal_year', fiscalYear);
            existing.query();
            if (!existing.next()) {
                var rec = new GlideRecord('x_2248447_csr_ma_2_recognition');
                rec.initialize();
                rec.setValue('employee', employeeId);
                rec.setValue('recognition_type', 'badge');
                rec.setValue('badge_level', badgeLevel);
                rec.setValue('milestone_hours', milestone);
                rec.setValue('fiscal_year', fiscalYear);
                rec.setValue('awarded_on', new GlideDateTime().getValue());
                rec.setValue('event', eventId);
                rec.insert();
                gs.info('CSR: Awarded ' + badgeLevel + ' badge to employee for reaching ' + milestone + ' hours.');
            }
        }
    }
}
export function updateStreak(current, previous) {
    var newStatus = current.getValue('status');
    var oldStatus = previous.getValue('status');
    if (newStatus !== 'completed' || oldStatus === 'completed')
        return;
    var employeeId = current.getValue('employee');
    var eventId = current.getValue('event');
    if (!employeeId || !eventId)
        return;
    var evt = new GlideRecord('x_2248447_csr_ma_2_event');
    if (!evt.get(eventId))
        return;
    var eventDate = evt.getValue('event_date');
    if (!eventDate)
        return;
    var eventMonth = eventDate.substring(0, 7); // YYYY-MM
    var fiscalYear = eventDate.substring(0, 4);
    var streak = new GlideRecord('x_2248447_csr_ma_2_streak');
    streak.addQuery('employee', employeeId);
    streak.addQuery('fiscal_year', fiscalYear);
    streak.query();
    if (streak.next()) {
        var lastMonth = streak.getValue('last_participation_month') || '';
        if (lastMonth === eventMonth)
            return; // Already counted this month
        var currentStreak = parseInt(streak.getValue('current_streak')) || 0;
        var longestStreak = parseInt(streak.getValue('longest_streak')) || 0;
        // Check if consecutive month
        if (lastMonth) {
            var lastParts = lastMonth.split('-');
            var lastYr = parseInt(lastParts[0]);
            var lastMo = parseInt(lastParts[1]);
            var evtParts = eventMonth.split('-');
            var evtYr = parseInt(evtParts[0]);
            var evtMo = parseInt(evtParts[1]);
            var monthDiff = (evtYr - lastYr) * 12 + (evtMo - lastMo);
            if (monthDiff === 1) {
                currentStreak++;
            }
            else {
                currentStreak = 1;
            }
        }
        else {
            currentStreak = 1;
        }
        if (currentStreak > longestStreak)
            longestStreak = currentStreak;
        streak.setValue('current_streak', currentStreak);
        streak.setValue('longest_streak', longestStreak);
        streak.setValue('last_participation_month', eventMonth);
        streak.setValue('updated_on', new GlideDateTime().getValue());
        streak.update();
    }
    else {
        var newStreak = new GlideRecord('x_2248447_csr_ma_2_streak');
        newStreak.initialize();
        newStreak.setValue('employee', employeeId);
        newStreak.setValue('fiscal_year', fiscalYear);
        newStreak.setValue('current_streak', 1);
        newStreak.setValue('longest_streak', 1);
        newStreak.setValue('last_participation_month', eventMonth);
        newStreak.setValue('updated_on', new GlideDateTime().getValue());
        newStreak.insert();
    }
}
